const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
test({ sr: 'prvi poziv se izvršava odmah i vraća rezultat', en: 'the first call runs immediately and returns the result' }, () => {
  const t = throttle((x) => x * 2, 50);
  expect(t(21)).toBe(42);
});
test({ sr: 'pozivi unutar prozora se ignorišu', en: 'calls inside the window are ignored' }, () => {
  let calls = 0;
  const t = throttle(() => { calls++; }, 50);
  t(); t(); t();
  expect(calls).toBe(1);
});
test({ sr: 'ignorisan poziv vraća rezultat poslednjeg izvršenog', en: 'an ignored call returns the result of the last executed one' }, () => {
  const t = throttle((x) => x * 2, 50);
  expect(t(2)).toBe(4);
  expect(t(5)).toBe(4);
});

