test('the next call goes through after the window', async () => {
  let calls = 0;
  const t = throttle(() => { calls++; }, 30);
  t(); t();
  expect(calls).toBe(1);
  await wait(100);
  t();
  expect(calls).toBe(2);
});
test('fn receives the arguments of the executed call', () => {
  const seen = [];
  const t = throttle((x) => { seen.push(x); }, 50);
  t(1); t(2); t(3);
  expect(seen).toEqual([1]);
});
test('ignored calls do not move the window', async () => {
  let calls = 0;
  const t = throttle(() => { calls++; }, 300);
  t();
  await wait(150);
  t();
  expect(calls).toBe(1);
  await wait(225);
  t();
  expect(calls).toBe(2);
});
test('every throttled function has its own state', () => {
  let a = 0;
  let b = 0;
  const ta = throttle(() => { a++; }, 50);
  const tb = throttle(() => { b++; }, 50);
  ta(); tb();
  expect(a).toBe(1);
  expect(b).toBe(1);
});
test('a new window gives a new result', async () => {
  const t = throttle((x) => x * 2, 30);
  expect(t(2)).toBe(4);
  await wait(100);
  expect(t(5)).toBe(10);
  expect(t(7)).toBe(10);
});

