function throttle(fn, ms) {
  let waiting = false;
  let lastResult;
  return (...args) => {
    if (waiting) return lastResult;
    waiting = true;
    setTimeout(() => { waiting = false; }, ms);
    lastResult = fn(...args);
    return lastResult;
  };
}

function throttle(fn, ms) {
  let last = -Infinity;
  let lastResult;
  return (...args) => {
    const now = Date.now();
    if (now - last < ms) return lastResult;
    last = now;
    lastResult = fn(...args);
    return lastResult;
  };
}
